defaultSource "javascript/crypto_vectors.mjs" = "// Generated by LawSpec. Do not edit.\n// Known-answer tests of lawspec.crypto's default handlers, against NIST's\n// vectors (see docs/reference/language/cryptography.md for the sources).\nimport { test } from 'node:test';\nimport assert from 'node:assert/strict';\nimport { createHash } from 'node:crypto';\nimport { ml_kem768 } from '@noble/post-quantum/ml-kem.js';\nimport { ml_dsa65 } from '@noble/post-quantum/ml-dsa.js';\nimport * as crypto from '../src/lawspec/crypto.mjs';\nconst vectorText = String.raw `@@VECTORS@@`;\nfunction vectors(kind) {\n    const found = vectorText.split('\\n').map((line) => line.trim().split(/\\s+/))\n        .filter((fields) => fields[0] === kind).map((fields) => fields.slice(1).map((f) => (f === '-' ? '' : f)));\n    assert.ok(found.length > 0, kind);\n    return found;\n}\nconst unhex = (text) => new Uint8Array(Buffer.from(text, 'hex'));\nconst hex = (data) => Buffer.from(data).toString('hex');\nconst sha3 = (data) => createHash('sha3-256').update(data).digest('hex');\nconst flipped = (data) => { const copy = new Uint8Array(data); copy[0] ^= 1; return copy; };\ntest('SHA3-256', () => {\n    for (const [message, digest] of vectors('sha3-256'))\n        assert.equal(hex(crypto.sha3_256(unhex(message))), digest);\n});\ntest('SHAKE256', () => {\n    for (const [message, length, output] of vectors('shake256'))\n        assert.equal(hex(crypto.shake256(unhex(message), Number(length))), output);\n});\ntest('AES-256-GCM', () => {\n    for (const [key, iv, plaintext, associated, ciphertext, tag] of vectors('aes-256-gcm')) {\n        const sealed = crypto.aes256GcmEncrypt(unhex(key), unhex(iv), unhex(plaintext), unhex(associated));\n        assert.equal(hex(sealed), ciphertext + tag);\n        assert.equal(hex(crypto.aes256GcmDecrypt(unhex(key), unhex(iv), sealed, unhex(associated)) ?? new Uint8Array([1])), plaintext);\n        assert.equal(crypto.aes256GcmDecrypt(unhex(key), unhex(iv), flipped(sealed), unhex(associated)), undefined);\n    }\n});\ntest('ML-KEM-768 key generation', () => {\n    for (const [d, z, publicDigest, secretDigest] of vectors('mlkem768-keygen')) {\n        const { publicKey, secretKey } = ml_kem768.keygen(unhex(d + z));\n        assert.equal(sha3(publicKey), publicDigest);\n        assert.equal(sha3(secretKey), secretDigest);\n        assert.equal(hex(crypto.mlKem768KeyPairFromSeed(unhex(d + z)).publicKey), hex(publicKey));\n    }\n});\ntest('ML-KEM-768 encapsulation', () => {\n    for (const [publicKey, message, ciphertext, secret] of vectors('mlkem768-encaps')) {\n        const made = crypto.mlKem768Encapsulate(unhex(publicKey), unhex(message));\n        assert.equal(hex(made.ciphertext), ciphertext);\n        assert.equal(hex(made.secret), secret);\n    }\n});\ntest('ML-KEM-768 decapsulation', () => {\n    for (const [secretKey, ciphertext, secret] of vectors('mlkem768-decaps')) {\n        assert.equal(hex(crypto.mlKem768DecapsulateExpanded(unhex(secretKey), unhex(ciphertext))), secret);\n    }\n    for (const [seed, ciphertext, secret] of vectors('mlkem768-decaps-seed')) {\n        assert.equal(hex(crypto.mlKem768Decapsulate(unhex(seed), unhex(ciphertext))), secret);\n    }\n});\ntest('ML-DSA-65 key generation', () => {\n    for (const [seed, publicDigest, secretDigest] of vectors('mldsa65-keygen')) {\n        const { publicKey, secretKey } = ml_dsa65.keygen(unhex(seed));\n        assert.equal(sha3(publicKey), publicDigest);\n        assert.equal(sha3(secretKey), secretDigest);\n        assert.equal(sha3(crypto.mlDsa65PublicKey(unhex(seed))), publicDigest);\n    }\n});\ntest('ML-DSA-65 verification', () => {\n    for (const [publicKey, message, context, signature, passed] of vectors('mldsa65-verify')) {\n        assert.equal(crypto.mlDsa65Verify(unhex(publicKey), unhex(message), unhex(signature), unhex(context)), passed === 'true');\n    }\n});\ntest('ML-DSA-65 deterministic signature', () => {\n    for (const [seed, message, signature] of vectors('mldsa65-sign-seed')) {\n        assert.equal(hex(crypto.mlDsa65Sign(unhex(seed), unhex(message), new Uint8Array(0), true)), signature);\n        const publicKey = crypto.mlDsa65PublicKey(unhex(seed));\n        assert.ok(crypto.mlDsa65Verify(publicKey, unhex(message), unhex(signature)));\n        assert.ok(!crypto.mlDsa65Verify(publicKey, flipped(unhex(message)), unhex(signature)));\n    }\n});\ntest('SLH-DSA-SHAKE-128f key generation', () => {\n    for (const [skSeed, skPrf, pkSeed, publicKey, secretDigest] of vectors('slhdsa128f-keygen')) {\n        const made = crypto.slhDsaKeyPair(unhex(skSeed), unhex(skPrf), unhex(pkSeed));\n        assert.equal(hex(made.publicKey), publicKey);\n        assert.equal(sha3(made.secretKey), secretDigest);\n    }\n});\ntest('SLH-DSA-SHAKE-128f verification', () => {\n    for (const [publicKey, message, context, signature, passed] of vectors('slhdsa128f-verify')) {\n        assert.equal(crypto.slhDsaVerify(unhex(publicKey), unhex(message), unhex(signature), unhex(context)), passed === 'true');\n        assert.ok(!crypto.slhDsaVerify(unhex(publicKey), flipped(unhex(message)), unhex(signature), unhex(context)));\n    }\n});\ntest('SLH-DSA-SHAKE-128f round trip', () => {\n    for (const [skSeed, skPrf, pkSeed] of vectors('slhdsa128f-keygen')) {\n        const { publicKey, secretKey } = crypto.slhDsaKeyPair(unhex(skSeed), unhex(skPrf), unhex(pkSeed));\n        const message = new TextEncoder().encode('LawSpec');\n        const signature = crypto.slhDsaSign(secretKey, message);\n        assert.ok(crypto.slhDsaVerify(publicKey, message, signature));\n        assert.ok(!crypto.slhDsaVerify(publicKey, flipped(message), signature));\n    }\n});\n"
