defaultSource "javascript/system.mjs" = "// Generated by LawSpec. Do not edit.\n// The default handlers of lawspec.system: the process's file system,\n// environment and free ports.\nimport * as fs from 'node:fs';\nimport { execFileSync } from 'node:child_process';\nimport * as data from '../lawspec_data.mjs';\n/** Files by path; a relative path is from the working directory. */\nexport class FileSystemHandler {\n    readBytes(value0) {\n        try {\n            return new data.Just(new Uint8Array(fs.readFileSync(value0)));\n        }\n        catch {\n            return new data.Nothing();\n        }\n    }\n    writeBytes(value0, value1) {\n        fs.writeFileSync(value0, value1);\n    }\n    pathExists(value0) {\n        try {\n            fs.lstatSync(value0);\n            return true;\n        }\n        catch {\n            return false;\n        }\n    }\n    removePath(value0) {\n        fs.rmSync(value0, { recursive: true, force: true });\n    }\n}\nexport function validName(name) {\n    return name !== '' && !name.includes('=') && !name.includes('\\0');\n}\n/** The process's environment. */\nexport class EnvironmentHandler {\n    environmentVariable(value0) {\n        const value = validName(value0) ? process.env[value0] : undefined;\n        return value === undefined ? new data.Nothing() : new data.Just(value);\n    }\n}\n// Node binds sockets only asynchronously, so a child process asks.\nconst probe = \"const s=require('net').createServer();s.listen(0,'127.0.0.1',()=>{process.stdout.write(String(s.address().port));s.close();});\";\n/** A TCP port on 127.0.0.1 the operating system reports free. */\nexport class PortsHandler {\n    freePort() {\n        return Number(execFileSync(process.execPath, ['-e', probe], { encoding: 'utf8' }));\n    }\n}\n"
