defaultSource "python/crypto.py" = "# Generated by LawSpec. Do not edit.\n\"\"\"The default handlers of lawspec.crypto: SHA3-256 and SHAKE256 (FIPS 202),\nML-KEM-768 (FIPS 203), ML-DSA-65 (FIPS 204), AES-256-GCM, and SLH-DSA-SHAKE-128f\n(FIPS 205) as the alternative Signature handler.\n\nML-KEM, ML-DSA and AES-GCM come from the cryptography package (pip install\ncryptography; its wheels carry OpenSSL). SHA3 and SHAKE come from hashlib.\nSLH-DSA is implemented here, over hashlib's SHAKE256.\n\nA secret key's bytes are its seed: d || z (64 bytes) for ML-KEM-768 (FIPS 203,\nML-KEM.KeyGen_internal) and xi (32 bytes) for ML-DSA-65 (FIPS 204,\nML-DSA.KeyGen_internal). Public keys, ciphertexts and signatures are the\nstandards' encodings.\"\"\"\nimport builtins as _builtins\nimport hashlib as _hashlib\nimport os as _os\n\nimport lawspec_data as data\nimport lawspec_schema as _schema\nimport lawspec_runtime as ls\n\n\ndef _cryptography():\n    try:\n        from cryptography.hazmat.primitives.asymmetric import mldsa, mlkem\n        from cryptography.hazmat.primitives.ciphers.aead import AESGCM\n        from cryptography.exceptions import InvalidSignature, InvalidTag\n    except ImportError as error:\n        raise ImportError(\"lawspec.crypto's default handlers need the cryptography package: \"\n                          \"python -m pip install cryptography\") from error\n    return mlkem, mldsa, AESGCM, InvalidSignature, InvalidTag\n\n\n# FIPS 202.\n\ndef sha3_256(message: bytes) -> bytes:\n    return _hashlib.sha3_256(message).digest()\n\n\ndef shake256(message: bytes, length: int) -> bytes:\n    return _hashlib.shake_256(message).digest(max(length, 0))\n\n\n# FIPS 203: ML-KEM-768. A secret key is the seed d || z.\n\ndef ml_kem_768_key_pair_from_seed(seed: bytes) -> tuple[bytes, bytes]:\n    mlkem = _cryptography()[0]\n    key = mlkem.MLKEM768PrivateKey.from_seed_bytes(seed)\n    return key.public_key().public_bytes_raw(), key.private_bytes_raw()\n\n\ndef ml_kem_768_encapsulate(public_key: bytes) -> tuple[bytes, bytes]:\n    \"\"\"The ciphertext and the shared secret.\"\"\"\n    mlkem = _cryptography()[0]\n    secret, ciphertext = mlkem.MLKEM768PublicKey.from_public_bytes(public_key).encapsulate()\n    return ciphertext, secret\n\n\ndef ml_kem_768_decapsulate(seed: bytes, ciphertext: bytes) -> bytes:\n    mlkem = _cryptography()[0]\n    return mlkem.MLKEM768PrivateKey.from_seed_bytes(seed).decapsulate(ciphertext)\n\n\n# FIPS 204: ML-DSA-65. A secret key is the seed xi.\n\ndef ml_dsa_65_public_key(seed: bytes) -> bytes:\n    mldsa = _cryptography()[1]\n    return mldsa.MLDSA65PrivateKey.from_seed_bytes(seed).public_key().public_bytes_raw()\n\n\ndef ml_dsa_65_sign(seed: bytes, message: bytes, context: bytes = b\"\") -> bytes:\n    mldsa = _cryptography()[1]\n    key = mldsa.MLDSA65PrivateKey.from_seed_bytes(seed)\n    return key.sign(message, context) if context else key.sign(message)\n\n\ndef ml_dsa_65_verify(public_key: bytes, message: bytes, signature: bytes, context: bytes = b\"\") -> bool:\n    mldsa, invalid = _cryptography()[1], _cryptography()[3]\n    try:\n        key = mldsa.MLDSA65PublicKey.from_public_bytes(public_key)\n        if context:\n            key.verify(signature, message, context)\n        else:\n            key.verify(signature, message)\n        return True\n    except (invalid, ValueError):\n        return False\n\n\n# AES-256-GCM: a sealed message is the 12-byte nonce, the ciphertext and the\n# 16-byte tag.\n\ndef aes_256_gcm_encrypt(key: bytes, nonce: bytes, plaintext: bytes, associated: bytes) -> bytes:\n    AESGCM = _cryptography()[2]\n    return AESGCM(key).encrypt(nonce, plaintext, associated)\n\n\ndef aes_256_gcm_decrypt(key: bytes, nonce: bytes, ciphertext: bytes, associated: bytes):\n    AESGCM, invalid = _cryptography()[2], _cryptography()[4]\n    if len(key) != 32 or len(nonce) != 12 or len(ciphertext) < 16:\n        return None\n    try:\n        return AESGCM(key).decrypt(nonce, ciphertext, associated)\n    except invalid:\n        return None\n\n\n# FIPS 205: SLH-DSA-SHAKE-128f (n 16, h 66, d 22, h' 3, a 6, k 33, lg w 4,\n# m 34). A secret key is SK.seed || SK.prf || PK.seed || PK.root.\n\n_N, _H, _D, _HP, _A, _K, _LGW, _M = 16, 66, 22, 3, 6, 33, 4, 34\n_W = 1 << _LGW\n_LEN1, _LEN2 = 32, 3\n_LEN = _LEN1 + _LEN2\n_WOTS_HASH, _WOTS_PK, _TREE, _FORS_TREE, _FORS_ROOTS, _WOTS_PRF, _FORS_PRF = range(7)\nSLH_DSA_SIGNATURE_BYTES = (1 + _K * (1 + _A) + _H + _D * _LEN) * _N\n\n\ndef _shake(*parts: bytes, length: int = _N) -> bytes:\n    return _hashlib.shake_256(b\"\".join(parts)).digest(length)\n\n\nclass _Address:\n    \"\"\"ADRS (FIPS 205, section 4.2): layer, tree, type and three words.\"\"\"\n\n    __slots__ = (\"bytes\",)\n\n    def __init__(self, raw: bytes = bytes(32)):\n        self.bytes = bytearray(raw)\n\n    def copy(self):\n        return _Address(self.bytes)\n\n    def _set(self, offset, size, value):\n        self.bytes[offset:offset + size] = value.to_bytes(size, \"big\")\n\n    def layer(self, value):\n        self._set(0, 4, value)\n\n    def tree(self, value):\n        self._set(4, 12, value)\n\n    def type_and_clear(self, value):\n        self._set(16, 4, value)\n        self.bytes[20:32] = bytes(12)\n\n    def key_pair(self, value):\n        self._set(20, 4, value)\n\n    def get_key_pair(self):\n        return int.from_bytes(self.bytes[20:24], \"big\")\n\n    def chain(self, value):\n        self._set(24, 4, value)\n\n    tree_height = chain\n\n    def hash(self, value):\n        self._set(28, 4, value)\n\n    tree_index = hash\n\n    def get_tree_index(self):\n        return int.from_bytes(self.bytes[28:32], \"big\")\n\n    def raw(self):\n        return bytes(self.bytes)\n\n\ndef _base_2b(x: bytes, b: int, count: int) -> list[int]:\n    out, position, bits, total = [], 0, 0, 0\n    for _ in range(count):\n        while bits < b:\n            total = (total << 8) + x[position]\n            position += 1\n            bits += 8\n        bits -