rn _wots_public(sk_seed, pk_seed, adrs)\n    left = _xmss_node(sk_seed, 2 * i, z - 1, pk_seed, adrs)\n    right = _xmss_node(sk_seed, 2 * i + 1, z - 1, pk_seed, adrs)\n    adrs.type_and_clear(_TREE)\n    adrs.tree_height(z)\n    adrs.tree_index(i)\n    return _shake(pk_seed, adrs.raw(), left, right)\n\n\ndef _xmss_sign(message, sk_seed, index, pk_seed, adrs):\n    path = [_xmss_node(sk_seed, (index >> j) ^ 1, j, pk_seed, adrs) for j in range(_HP)]\n    adrs.type_and_clear(_WOTS_HASH)\n    adrs.key_pair(index)\n    return _wots_sign(message, sk_seed, pk_seed, adrs) + b\"\".join(path)\n\n\ndef _xmss_public_from_signature(index, signature, message, pk_seed, adrs):\n    adrs.type_and_clear(_WOTS_HASH)\n    adrs.key_pair(index)\n    node = _wots_public_from_signature(signature[:_LEN * _N], message, pk_seed, adrs)\n    adrs.type_and_clear(_TREE)\n    tree_index = index\n    for k in range(_HP):\n        sibling = signature[(_LEN + k) * _N:(_LEN + k + 1) * _N]\n        adrs.tree_height(k + 1)\n        if (index >> k) % 2 == 0:\n            tree_index //= 2\n            adrs.tree_index(tree_index)\n            node = _shake(pk_seed, adrs.raw(), node, sibling)\n        else:\n            tree_index = (tree_index - 1) // 2\n            adrs.tree_index(tree_index)\n            node = _shake(pk_seed, adrs.raw(), sibling, node)\n    return node\n\n\n_XMSS_BYTES = (_LEN + _HP) * _N\n\n\ndef _ht_sign(message, sk_seed, pk_seed, tree, leaf):\n    adrs = _Address()\n    adrs.tree(tree)\n    signature = _xmss_sign(message, sk_seed, leaf, pk_seed, adrs)\n    parts = [signature]\n    root = _xmss_public_from_signature(leaf, signature, message, pk_seed, adrs)\n    for j in range(1, _D):\n        leaf = tree % (1 << _HP)\n        tree >>= _HP\n        adrs.layer(j)\n        adrs.tree(tree)\n        signature = _xmss_sign(root, sk_seed, leaf, pk_seed, adrs)\n        parts.append(signature)\n        if j < _D - 1:\n            root = _xmss_public_from_signature(leaf, signature, root, pk_see