defaultSource "python/log.py" = "# Generated by LawSpec. Do not edit.\n\"\"\"The default handlers of lawspec.log: the logging module's \"lawspec\"\nlogger. Laws that inspect what was logged use `recording Log`.\"\"\"\nimport builtins as _builtins\nimport logging as _logging\n\nimport lawspec_data as data\n\n_LOGGER = _logging.getLogger(\"lawspec\")\n_LEVELS = {\n    @@LogLevel/Debug@@: _logging.DEBUG,\n    @@LogLevel/Info@@: _logging.INFO,\n    @@LogLevel/Warning@@: _logging.WARNING,\n    @@LogLevel/Error@@: _logging.ERROR,\n}\n\n\nclass LogHandler:\n    \"\"\"Logs to the \"lawspec\" logger.\"\"\"\n\n    def logMessage(self, value0: @@LogLevel@@, value1: _builtins.str) -> None:\n        _LOGGER.log(_LEVELS.get(type(value0), _logging.INFO), value1)\n\n\nclass TraceHandler:\n    \"\"\"Trace events, at debug level on the \"lawspec.trace\" logger.\"\"\"\n\n    def traceEvent(self, value0: _builtins.str) -> None:\n        _logging.getLogger(\"lawspec.trace\").debug(value0)\n"
defaultSource "python/random.py" = "# Generated by LawSpec. Do not edit.\n\"\"\"The default handlers of lawspec.random. Random is the generator of\n`seeded random n` (a 64-bit linear congruential generator, the same on every\ntarget), started at the run's seed: LAWSPEC_SEED, or 0. SecureRandom is the\noperating system's cryptographically secure generator.\"\"\"\nimport builtins as _builtins\nimport os as _os\nimport secrets as _secrets\n\n_MODULUS = 1 << 64\n\n\ndef random_step(state: int) -> int:\n    return (6364136223846793005 * (state % _MODULUS) + 1442695040888963407) % _MODULUS\n\n\ndef random_draw(state: int, bound: int) -> int:\n    \"\"\"A draw from 0 up to bound, as lawspec.random's randomDraw makes it.\"\"\"\n    if bound < 1:\n        return 0\n    first = random_step(state)\n    bits = (first >> 32 << 32) + (random_step(first) >> 32)\n    return bits % bound\n\n\ndef run_seed() -> int:\n    value = _os.environ.get(\"LAWSPEC_SEED\")\n    return int(value) % _MODULUS if value else 0\n\n\nclass RandomHandler:\n    \"\"\"Reproducible draws from the run's seed.\"\"\"\n\n    def __init__(self, seed: int | None = None):\n        self._state = run_seed() if seed is None else seed % _MODULUS\n\n    def randomBelow(self, value0: _builtins.int) -> _builtins.int:\n        state = self._state\n        self._state = random_step(random_step(state))\n        return random_draw(state, value0)\n\n\nclass SecureRandomHandler:\n    \"\"\"The operating system's generator (secrets).\"\"\"\n\n    def secureBytes(self, value0: _builtins.int) -> _builtins.bytes:\n        return _secrets.token_bytes(max(value0, 0))\n\n    def secureBelow(self, value0: _builtins.int) -> _builtins.int:\n        return _secrets.randbelow(value0) if value0 >= 1 else 0\n\n    def secureToken(self) -> _builtins.str:\n        return _secrets.token_hex(32)\n"
