  probe.bind((\"127.0.0.1\", 0))\n            return probe.getsockname()[1]\n"
defaultSource "python/test_crypto_vectors.py" = "# Generated by LawSpec. Do not edit.\n\"\"\"Known-answer tests of lawspec.crypto's default handlers, against NIST's\nvectors (see docs/reference/language/cryptography.md for the sources).\"\"\"\nimport hashlib\n\nimport lawspec.crypto as crypto\n\nVECTORS = \"\"\"@@VECTORS@@\"\"\"\n\n\ndef vectors(kind):\n    found = []\n    for line in VECTORS.splitlines():\n        fields = line.split()\n        if fields and fields[0] == kind:\n            found.append([b\"\" if f == \"-\" else f for f in fields[1:]])\n    assert found, kind\n    return found\n\n\ndef unhex(text):\n    return bytes.fromhex(text) if isinstance(text, str) else b\"\"\n\n\ndef sha3(data):\n    return hashlib.sha3_256(data).hexdigest()\n\n\ndef test_sha3_256():\n    for message, digest in vectors(\"sha3-256\"):\n        assert crypto.sha3_256(unhex(message)).hex() == digest\n\n\ndef test_shake256():\n    for message, length, output in vectors(\"shake256\"):\n        assert crypto.shake256(unhex(message), int(length)).hex() == output\n\n\ndef test_aes_256_gcm():\n    for key, iv, plaintext, associated, ciphertext, tag in vectors(\"aes-256-gcm\"):\n        sealed = crypto.aes_256_gcm_encrypt(unhex(key), unhex(iv), unhex(plaintext), unhex(associated))\n        assert sealed == unhex(ciphertext) + unhex(tag)\n        assert crypto.aes_256_gcm_decrypt(unhex(key), unhex(iv), sealed, unhex(associated)) == unhex(plaintext)\n        tampered = bytes([sealed[0] ^ 1]) + sealed[1:]\n        assert crypto.aes_256_gcm_decrypt(unhex(key), unhex(iv), tampered, unhex(associated)) is None\n\n\ndef test_ml_kem_768_key_generation():\n    for d, z, public_digest, _ in vectors(\"mlkem768-keygen\"):\n        public, secret = crypto.ml_kem_768_key_pair_from_seed(unhex(d) + unhex(z))\n        assert sha3(public) == public_digest\n        assert secret == unhex(d) + unhex(z)\n\n\ndef test_ml_kem_768_decapsulation_from_a_seed():\n    # cryptography takes decapsulation keys as seeds, and encapsulates only\n    # with fresh randomness, so the ACVP encapsulation and expanded-key\n    # vectors are checked where a library allows it.\n    for seed, ciphertext, secret in vectors(\"mlkem768-decaps-seed\"):\n        assert crypto.ml_kem_768_decapsulate(unhex(seed), unhex(ciphertext)).hex() == secret\n\n\ndef test_ml_kem_768_round_trip():\n    for seed, _, _ in vectors(\"mlkem768-decaps-seed\"):\n        public, secret = crypto.ml_kem_768_key_pair_from_seed(unhex(seed))\n        ciphertext, shared = crypto.ml_kem_768_encapsulate(public)\n        assert crypto.ml_kem_768_decapsulate(secret, ciphertext) == shared\n\n\ndef test_ml_dsa_65_key_generation():\n    for seed, public_digest, _ in vectors(\"mldsa65-keygen\"):\n        assert sha3(crypto.ml_dsa_65_public_key(unhex(seed))) == public_digest\n\n\ndef test_ml_dsa_65_verification():\n    for public, message, context, signature, passed in vectors(\"mldsa65-verify\"):\n        assert crypto.ml_dsa_65_verify(unhex(public), unhex(message), unhex(signature), unhex(context)) == (passed == \"true\")\n\n\ndef test_ml_dsa_65_signature_from_a_seed():\n    # cryptography signs hedged only, so the deterministic signature is\n    # verified, not compared.\n    for seed, message, signature in vectors(\"mldsa65-sign-seed\"):\n        public = crypto.ml_dsa_65_public_key(unhex(seed))\n        assert crypto.ml_dsa_65_verify(public, unhex(message), unhex(signature))\n        assert not crypto.ml_dsa_65_verify(public, unhex(message) + b\"\\0\", unhex(signature))\n        assert crypto.ml_dsa_65_verify(public, unhex(message), crypto.ml_dsa_65_sign(unhex(seed), unhex(message)))\n\n\ndef test_slh_dsa_shake_128f_key_generation():\n    for sk_seed, sk_prf, pk_seed, public, secret_digest in vectors(\"slhdsa128f-keygen\"):\n        made_public, made_secret = crypto.slh_dsa_key_pair(unhex(sk_seed), unhex(sk_prf), unhex(pk_seed))\n        assert made_public.hex() == public\n        assert sha3(made_secret) == secret_digest\n\n\ndef test_slh_dsa_shake_128f_verification():\n    for public, message, context, signature, passed in vectors(\"slhdsa128f-verify\"):\n        assert crypto.slh_dsa_verify(unhex(public), unhex(message), unhex(signature), unhex(context)) == (passed == \"true\")\n        changed = bytes([unhex(message)[0] ^ 1]) + unhex(message)[1:]\n        assert not crypto.slh_dsa_verify(unhex(public), changed, unhex(signature), unhex(context))\n\n\ndef test_slh_dsa_shake_128f_round_trip():\n    for sk_seed, sk_prf, pk_seed, _, _ in vectors(\"slhdsa128f-keygen\"):\n        public, secret = crypto.slh_dsa_key_pair(unhex(sk_seed), unhex(sk_prf), unhex(pk_seed))\n        signature = crypto.slh_dsa_sign(secret, b\"LawSpec\")\n        assert crypto.slh_dsa_verify(public, b\"LawSpec\", signature)\n        assert not crypto.slh_dsa_verify(public, b\"LawSpeC\", signature)\n"
defaultSource "python/time.py" = "# Generated by LawSpec. Do not edit.\n\"\"\"The default handler of lawspec.time's Clock: the system clock, kept from\ngoing back by a monotonic clock. An Instant is microseconds since\n1970-01-01T00:00:00Z.\"\"\"\nimport time as _time\n\nimport lawspec_data as data\nimport lawspec_runtime as ls\n\n_WALL = _time.time_ns() // 1000\n_MONOTONIC = _time.monotonic_ns() // 1000\n\n\ndef now_micros() -> int:\n    \"\"\"The wall clock at start, moved on by the monotonic clock since.\"\"\"\n    return _WALL + (_time.monotonic_ns() // 1000 - _MONOTONIC)\n\n\nclass ClockHandler:\n    \"\"\"The system clock. now never goes back; sleep blocks this thread.\"\"\"\n\n    def now(self) -> @@Instant@@:\n        return @@Instant@@(now_micros())\n\n    def sleep(self, value0: ls.timedelta) -> None:\n        target = now_micros() + value0 // ls.timedelta(microseconds=1)\n        while (left := target - now_micros()) > 0:\n            _time.sleep(left / 1000000)\n"
