defaultSource "typescript/crypto.ts" = "// Generated by LawSpec. Do not edit.\n// The default handlers of lawspec.crypto: SHA3-256 and SHAKE256 (FIPS 202),\n// ML-KEM-768 (FIPS 203), ML-DSA-65 (FIPS 204), AES-256-GCM, and\n// SLH-DSA-SHAKE-128f (FIPS 205) as the alternative Signature handler.\n//\n// ML-KEM, ML-DSA and SLH-DSA come from @noble/post-quantum; SHA3, SHAKE,\n// AES-GCM and randomness from node:crypto.\n//\n// A secret key's bytes are its seed: d || z (64 bytes) for ML-KEM-768 and xi\n// (32 bytes) for ML-DSA-65. Public keys, ciphertexts and signatures are the\n// standards' encodings.\nimport { createCipheriv, createDecipheriv, createHash, randomBytes } from 'node:crypto';\nimport { ml_kem768 } from '@noble/post-quantum/ml-kem.js';\nimport { ml_dsa65 } from '@noble/post-quantum/ml-dsa.js';\nimport { slh_dsa_shake_128f } from '@noble/post-quantum/slh-dsa.js';\nimport * as data from '../lawspec_data.js';\nimport type * as abilities from '../lawspec_abilities/lawspec/crypto.js';\n\nconst bytes = (buffer: Uint8Array): Uint8Array => new Uint8Array(buffer);\nconst empty = new Uint8Array(0);\n\n// FIPS 202.\nexport function sha3_256(message: Uint8Array): Uint8Array {\n  return bytes(createHash('sha3-256').update(message).digest());\n}\n\nexport function shake256(message: Uint8Array, length: number): Uint8Array {\n  return bytes(createHash('shake256', { outputLength: Math.max(length, 0) }).update(message).digest());\n}\n\n// FIPS 203: ML-KEM-768. A secret key is the seed d || z.\nexport function mlKem768KeyPairFromSeed(seed: Uint8Array): { publicKey: Uint8Array; secretKey: Uint8Array } {\n  return { publicKey: ml_kem768.keygen(seed).publicKey, secretKey: bytes(seed) };\n}\n\nexport function mlKem768Encapsulate(publicKey: Uint8Array, message?: Uint8Array): { ciphertext: Uint8Array; secret: Uint8Array } {\n  const { cipherText, sharedSecret } = ml_kem768.encapsulate(publicKey, message);\n  return { ciphertext: cipherText, secret: sharedSecret };\n}\n\nexport function mlKem768DecapsulateExpanded(secretKey: Uint8Array, ciphertext: Uint8Array): Uint8Array {\n  return ml_kem768.decapsulate(ciphertext, secretKey);\n}\n\nexport function mlKem768Decapsulate(seed: Uint8Array, ciphertext: Uint8Array): Uint8Array {\n  return ml_kem768.decapsulate(ciphertext, ml_kem768.keygen(seed).secretKey);\n}\n\n// FIPS 204: ML-DSA-65. A secret key is the seed xi.\nexport function mlDsa65PublicKey(seed: Uint8Array): Uint8Array {\n  return ml_dsa65.keygen(seed).publicKey;\n}\n\nexport function mlDsa65Sign(seed: Uint8Array, message: Uint8Array, context: Uint8Array = empty, deterministic = false): Uint8Array {\n  const { secretKey } = ml_dsa65.keygen(seed);\n  return ml_dsa65.sign(message, secretKey, deterministic ? { context, extraEntropy: false } : { context });\n}\n\nexport function mlDsa65Verify(publicKey: Uint8Array, message: Uint8Array, signature: Uint8Array, context: Uint8Array = empty): boolean {\n  try {\n    return ml_dsa65.verify(signature, message, publicKey, { context });\n  } catch {\n    return false;\n  }\n}\n\n// FIPS 205: SLH-DSA-SHAKE-128f. A secret key is SK.seed || SK.prf || PK.seed\n// || PK.root.\nexport function slhDsaKeyPair(skSeed: Uint8Array, skPrf: Uint8Array, pkSeed: Uint8Array): { publicKey: Uint8Array; secretKey: Uint8Array } {\n  const seed = new Uint8Array([...skSeed, ...skPrf, ...pkSeed]);\n  return slh_dsa_shake_128f.keygen(seed);\n}\n\nexport function slhDsaSign(secretKey: Uint8Array, message: Uint8Array, context: Uint8Array = empty): Uint8Array {\n  return slh_dsa_shake_128f.sign(message, secretKey, { context });\n}\n\nexport function slhDsaVerify(publicKey: Uint8Array, message: Uint8Array, signature: Uint8Array, context: Uint8Array = empty): boolean {\n  try {\n    return slh_dsa_shake_128f.verify(signature, message, publicKey, { context });\n  } catch {\n    return false;\n  }\n}\n\n// AES-256-GCM: a sealed message is the 12-byte nonce, the ciphertext and the\n// 16-byte tag.\nexport function aes256GcmEncrypt(key: Uint8Array, nonce: Uint8Array, plaintext: Uint8Array, associated: Uint8Array): Uint8Array {\n  const cipher = createCipheriv('aes-256-gcm', key, nonce);\n  cipher.setAAD(associated);\n  const body = Buffer.concat([cipher.update(plaintext), cipher.final()]);\n  return bytes(Buffer.concat([body, cipher.getAuthTag()]));\n}\n\nexport function aes256GcmDecrypt(key: Uint8Array, nonce: Uint8Array, sealed: Uint8Array, associated: Uint8Array): Uint8Array | undefined {\n  if (key.length !== 32 || nonce.length !== 12 || sealed.length < 16) return undefined;\n  try {\n    const decipher = createDecipheriv('aes-256-gcm', key, nonce);\n    decipher.setAAD(associated);\n    decipher.setAuthTag(sealed.subarray(sealed.length - 16));\n    return bytes(Buffer.concat([decipher.update(sealed.subarray(0, sealed.length - 16)), decipher.final()]));\n  } catch {\n    return undefined;\n  }\n}\n\n/** SHA3-256 and SHAKE256. */\nexport class HashHandler implements abilities.Hash {\n  sha3(value0: Uint8Array): @@Digest@@ {\n    return new @@Digest@@(sha3_256(value0));\n  }\n  shake(value0: Uint8Array, value1: number): Uint8Array {\n    return shake256(value0, value1);\n  }\n}\n\n/** ML-KEM-768. */\nexport class KeyExchangeHandler implements abilities.KeyExchange {\n  exchangeKeyPair(): @@ExchangeKeyPair@@ {\n    const { publicKey, secretKey } = mlKem768KeyPairFromSeed(bytes(randomBytes(64)));\n    return new @@ExchangeKeyPair@@(new @@ExchangePublicKey@@(publicKey), new @@ExchangeSecretKey@@(secretKey));\n  }\n  encapsulate(value0: @@ExchangePublicKey@@): @@Encapsulated@@ {\n    const { ciphertext, secret } = mlKem768Encapsulate(value0.value);\n    return new @@Encapsulated@@(new @@Ciphertext@@(ciphertext), new @@SharedSecret@@(secret));\n  }\n  decapsulate(value0: @@ExchangeSecretKey@@, value1: @@Ciphertext@@): @@SharedSecret@@ {\n    return new @@SharedSecret@@(mlKem768Decapsulate(value0.value, value1.value));\n  }\n}\n\n/** ML-DSA-65, hedged. */\nexport class SignatureHandler implements abilities.Signature {\n  signingKeyPair(): @@SigningKeyPair@@ {\n    const seed = bytes(randomBytes(32));\n    return new @@SigningKeyPair@@(new @@VerifyingKey@@(mlDsa65PublicKey(seed)), new @@SigningKey@@(seed));\n  }\n  sign(value0: @@SigningKey@@, value1: Uint8Array): @@SignatureBytes@@ {\n    return new @@SignatureBytes@@(mlDsa65Sign(value0.value, value1));\n  }\n  verify(value0: @@VerifyingKey@@, value1: Uint8Array, value2: @@SignatureBytes@@): boolean {\n    return mlDsa65Verify(value0.value, value1, value2.value);\n  }\n}\n\n/**\n * SLH-DSA-SHAKE-128f, hedged: the alternative Signature handler. Bind it in\n * lawspec.json: {\"ability\": \"lawspec.crypto::Signature\", \"native\": [\"lawspec\",\n * \"crypto\", \"SlhDsaSignatureHandler\"]}.\n */\nexport class SlhDsaSignatureHandler implements abilities.Signature {\n  signingKeyPair(): @@SigningKeyPair@@ {\n    const { publicKey, secretKey } = slhDsaKeyPair(bytes(randomBytes(16)), bytes(randomBytes(16)), bytes(randomBytes(16)));\n    return new @@SigningKeyPair@@(new @@VerifyingKey@@(publicKey), new @@SigningKey@@(secretKey));\n  }\n  sign(value0: @@SigningKey@@, value1: Uint8Array): @@SignatureBytes@@ {\n    return new @@SignatureBytes@@(slhDsaSign(value0.value, value1));\n  }\n  verify(value0: @@VerifyingKey@@, value1: Uint8Array, value2: @@SignatureBytes@@): boolean {\n    return slhDsaVerify(value0.value, value1, value2.value);\n  }\n}\n\n/** AES-256-GCM, a fresh random nonce per message. */\nexport class AeadHandler implements abilities.Aead {\n  aeadKey(): @@AeadKey@@ {\n    return new @@AeadKey@@(bytes(randomBytes(32)));\n  }\n  deriveAeadKey(value0: @@SharedSecret@@, value1: Uint8Array): @@AeadKey@@ {\n    return new @@AeadKey@@(shake256(new Uint8Array([...value0.value, ...value1]), 32));\n  }\n  seal(value0: @@AeadKey@@, value1: Uint8Array, value2: Uint8Array): @@Sealed@@ {\n    const nonce = bytes(randomBytes(12));\n    return new @@Sealed@@(new Uint8Array([...nonce, ...aes256GcmEncrypt(value0.value, nonce, value1, value2)]));\n  }\n  unseal(value0: @@AeadKey@@, value1: @@Sealed@@, value2: Uint8Array): data.Maybe<Uint8Array> {\n    const opened = aes256GcmDecrypt(value0.value, value1.value.subarray(0, 12), value1.value.subarray(12), value2);\n    return opened === undefined ? new data.Nothing() : new data.Just(opened);\n  }\n}\n"
defaultSource "typescript/crypto_vectors.ts" = "// Generated by LawSpec. Do not edit.\n// Known-answer tests of lawspec.crypto's default handlers, against NIST's\n// vectors (see docs/reference/language/cryptography.md for the sources).\nimport { test } from 'node:test';\nimport assert from 'node:assert/strict';\nimport { createHash } from 'node:crypto';\nimport { ml_kem768 } from '@noble/post-quantum/ml-kem.js';\nimport { ml_dsa65 } from '@noble/post-quantum/ml-dsa.js';\nimport * as crypto from '../src/lawspec/crypto.js';\n\nconst vectorText = String.raw`@@VECTORS@@`;\n\nfunction vectors(kind: string): string[][] {\n  const found = vectorText.split('\\n').map((line) => line.trim().split(/\\s+/))\n    .filter((fields) => fields[0] === kind).map((fields) => fields.slice(1).map((f) => (f === '-' ? '' : f)));\n  assert.ok(found.length > 0, kind);\n  return found;\n}\n\nconst unhex = (text: string): Uint8Array => new Uint8Array(Buffer.from(text, 'hex'));\nconst hex = (data: Uint8Array): string => Buffer.from(data).toString('hex');\nconst sha3 = (data: Uint8Array): string => createHash('sha3-256').update(data).digest('hex');\nconst flipped = (data: Uint8Array): Uint8Array => { const copy = new Uint8Array(data); copy[0] ^= 1; return copy; };\n\ntest('SHA3-256', () => {\n  for (const [message, digest] of vectors('sha3-256')) assert.equal(hex(crypto.sha3_256(unhex(message))), digest);\n});\n\ntest('SHAKE256', () => {\n  for (const [message, length, output] of vectors('shake256')) assert.equal(hex(crypto.shake256(unhex(message), Number(length))), output);\n});\n\ntest('AES-256-GCM', () => {\n  for (const [key, iv, plaintext, associated, ciphertext, tag] of vectors('aes-256-gcm')) {\n    const sealed = crypto.aes256GcmEncrypt(unhex(key), unhex(iv), unhex(plaintext), unhex(associated));\n    assert.equal(hex(sealed), ciphertext + tag);\n    assert.equal(hex(crypto.aes256GcmDecrypt(unhex(key), unhex(iv), sealed, unhex(associated)) ?? new Uint8Array([1])), plaintext);\n    assert.equal(crypto.aes256GcmDecrypt(unhex(key), unhex(iv), flipped(sealed), unhex(associated)), undefined);\n  }\n});\n\ntest('ML-KEM-768 key generation', () => {\n  for (const [d, z, publicDigest, secretDigest] of vectors('mlkem768-keygen')) {\n    const { publicKey, secretKey } = ml_kem768.keygen(unhex(d + z));\n    assert.equal(sha3(publicKey), publicDigest);\n    assert.equal(sha3(secretKey), secretDigest);\n    assert.equal(hex(crypto.mlKem768KeyPairFromSeed(unhex(d + z)).publicKey), hex(publicKey));\n  }\n});\n\ntest('ML-KEM-768 encapsulation', () => {\n  for (const [publicKey, message, ciphertext, secret] of vectors('mlkem768-encaps')) {\n    const made = crypto.mlKem768Encapsulate(unhex(publicKey), unhex(message));\n    assert.equal(hex(made.ciphertext), ciphertext);\n    assert.equal(hex(made.secret), secret);\n  }\n});\n\ntest('ML-KEM-768 decapsulation', () => {\n  for (const [secretKey, ciphertext, secret] of vectors('mlkem768-decaps')) {\n    assert.equal(hex(crypto.mlKem768DecapsulateExpanded(unhex(secretKey), unhex(ciphertext))), secret);\n  }\n  for (const [seed, ciphertext, secret] of vectors('mlkem768-decaps-seed')) {\n    assert.equal(hex(crypto.mlKem768Decapsulate(unhex(seed), unhex(ciphertext))), secret);\n  }\n});\n\ntest('ML-DSA-65 key generation', () => {\n  for (const [seed, publicDigest, secretDigest] of vectors('mldsa65-keygen')) {\n    const { publicKey, secretKey } = ml_dsa65.keygen(unhex(seed));\n    assert.equal(sha3(publicKey), publicDigest);\n    assert.equal(sha3(secretKey), secretDigest);\n    assert.equal(sha3(crypto.mlDsa65PublicKey(unhex(seed))), publicDigest);\n  }\n});\n\ntest('ML-DSA-65 verification', () => {\n  for (const [publicKey, message, context, signature, passed] of vectors('mldsa65-verify')) {\n    assert.equal(crypto.mlDsa65Verify(unhex(publicKey), unhex(message), unhex(signature), unhex(context)), passed === 'true');\n  }\n});\n\ntest('ML-DSA-65 deterministic signature', () => {\n  for (const [seed, message, signature] of vectors('mldsa65-sign-seed')) {\n    assert.equal(hex(crypto.mlDsa65Sign(unhex(seed), unhex(message), new Uint8Array(0), true)), signature);\n    const publicKey = crypto.mlDsa65PublicKey(unhex(seed));\n    assert.ok(crypto.mlDsa65Verify(publicKey, unhex(message), unhex(signature)));\n    assert.ok(!crypto.mlDsa65Verify(publicKey, flipped(unhex(message)), unhex(signature)));\n  }\n});\n\ntest('SLH-DSA-SHAKE-128f key generation', () => {\n  for (const [skSeed, skPrf, pkSeed, publicKey, secretDigest] of vectors('slhdsa128f-keygen')) {\n    const made = crypto.slhDsaKeyPair(unhex(skSeed), unhex(skPrf), unhex(pkSeed));\n    assert.equal(hex(made.publicKey), publicKey);\n    assert.equal(sha3(made.secretKey), secretDigest);\n  }\n});\n\ntest('SLH-DSA-SHAKE-128f verification', () => {\n  for (const [publicKey, message, context, signature, passed] of vectors('slhdsa128f-verify')) {\n    assert.equal(crypto.slhDsaVerify(unhex(publicKey), unhex(message), unhex(signature), unhex(context)), passed === 'true');\n    assert.ok(!crypto.slhDsaVerify(unhex(publicKey), flipped(unhex(message)), unhex(signature), unhex(context)));\n  }\n});\n\ntest('SLH-DSA-SHAKE-128f round trip', () => {\n  for (const [skSeed, skPrf, pkSeed] of vectors('slhdsa128f-keygen')) {\n    const { publicKey, secretKey } = crypto.slhDsaKeyPair(unhex(skSeed), unhex(skPrf), unhex(pkSeed));\n    const message = new TextEncoder().encode('LawSpec');\n    const signature = crypto.slhDsaSign(secretKey, message);\n    assert.ok(crypto.slhDsaVerify(publicKey, message, signature));\n    assert.ok(!crypto.slhDsaVerify(publicKey, flipped(message), signature));\n  }\n});\n"
defaultSource "typescript/log.ts" = "// Generated by LawSpec. Do not edit.\n// The default handlers of lawspec.log: the console. Laws that inspect what\n// was logged use `recording Log`.\nimport * as data from '../lawspec_data.js';\nimport type * as abilities from '../lawspec_abilities/lawspec/log.js';\n\n/** Logs to the console, at the matching level. */\nexport class LogHandler implements abilities.Log {\n  logMessage(value0: @@LogLevel@@, value1: string): void {\n    if (value0 instanceof @@LogLevel/Debug@@) console.debug(value1);\n    else if (value0 instanceof @@LogLevel/Warning@@) console.warn(value1);\n    else if (value0 instanceof @@LogLevel/Error@@) console.error(value1);\n    else console.info(value1);\n  }\n}\n\n/** Trace events, at debug level. */\nexport class TraceHandler implements abilities.Trace {\n  traceEvent(value0: string): void {\n    console.debug(`trace: ${value0}`);\n  }\n}\n"
defaultSource "typescript/random.ts" = "// Generated by LawSpec. Do not edit.\n// The default handlers of lawspec.random. Random is the generator of\n// `seeded random n` (a 64-bit linear congruential generator, the same on\n// every target), started at the run's seed: LAWSPEC_SEED, or 0. SecureRandom\n// is the operating system's cryptographically secure generator.\nimport { randomBytes } from 'node:crypto';\nimport type * as abilities from '../lawspec_abilities/lawspec/random.js';\n\nconst modulus = 1n << 64n;\n\nexport function randomStep(state: bigint): bigint {\n  return (6364136223846793005n * (((state % modulus) + modulus) % modulus) + 1442695040888963407n) % modulus;\n}\n\n/** A draw from 0 up to bound, as lawspec.random's randomDraw makes it. */\nexport function randomDraw(state: bigint, bound: bigint): bigint {\n  if (bound < 1n) return 0n;\n  const first = randomStep(state);\n  const bits = ((first >> 32n) << 32n) + (randomStep(first) >> 32n);\n  return bits % bound;\n}\n\nexport function runSeed(): bigint {\n  const value = process.env.LAWSPEC_SEED;\n  return value ? ((BigInt(value) % modulus) + modulus) % modulus : 0n;\n}\n\n/** Reproducible draws from the run's seed. */\nexport class RandomHandler implements abilities.Random {\n  private state: bigint;\n  constructor(seed?: bigint) {\n    this.state = seed === undefined ? runSeed() : ((seed % modulus) + modulus) % modulus;\n  }\n  randomBelow(value0: bigint): bigint {\n    const state = this.state;\n    this.state = randomStep(randomStep(state));\n    return randomDraw(state, value0);\n  }\n}\n\n/** A uniform draw from 0 up to bound, by rejection. */\nexport function secureBelow(bound: bigint): bigint {\n  if (bound < 1n) return 0n;\n  const limit = modulus - (modulus % bound);\n  for (;;) {\n    const draw = randomBytes(8).readBigUInt64BE();\n    if (draw < limit) return draw % bound;\n  }\n}\n\n/** The operating system's generator (node:crypto). */\nexport class SecureRandomHandler implements abilities.SecureRandom {\n  secureBytes(value0: number): Uint8Array {\n    return new Uint8Array(randomBytes(Math.max(value0, 0)));\n  }\n  secureBelow(value0: bigint): bigint {\n    return secureBelow(value0);\n  }\n  secureToken(): string {\n    return randomBytes(32).toString('hex');\n  }\n}\n"
defaultSource "typescript/system.ts" = "// Generated by LawSpec. Do not edit.\n// The default handlers of lawspec.system: the process's file system,\n// environment and free ports.\nimport * as fs from 'node:fs';\nimport { execFileSync } from 'node:child_process';\nimport * as data from '../lawspec_data.js';\nimport type * as abilities from '../lawspec_abilities/lawspec/system.js';\n\n/** Files by path; a relative path is from the working directory. */\nexport class FileSystemHandler implements abilities.FileSystem {\n  readBytes(value0: string): data.Maybe<Uint8Array> {\n    try {\n      return new data.Just(new Uint8Array(fs.readFileSync(value0)));\n    } catch {\n      return new data.Nothing();\n    }\n  }\n  writeBytes(value0: string, value1: Uint8Array): void {\n    fs.writeFileSync(value0, value1);\n  }\n  pathExists(value0: string): boolean {\n    try {\n      fs.lstatSync(value0);\n      return true;\n    } catch {\n      return false;\n    }\n  }\n  removePath(value0: string): void {\n    fs.rmSync(value0, { recursive: true, force: true });\n  }\n}\n\nexport function validName(name: string): boolean {\n  return name !== '' && !name.includes('=') && !name.includes('\\0');\n}\n\n/** The process's environment. */\nexport class EnvironmentHandler implements abilities.Environment {\n  environmentVariable(value0: string): data.Maybe<string> {\n    const value = validName(value0) ? process.env[value0] : undefined;\n    return value === undefined ? new data.Nothing() : new data.Just(value);\n  }\n}\n\n// Node binds sockets only asynchronously, so a child process asks.\nconst probe = \"const s=require('net').createServer();s.listen(0,'127.0.0.1',()=>{process.stdout.write(String(s.address().port));s.close();});\";\n\n/** A TCP port on 127.0.0.1 the operating system reports free. */\nexport class PortsHandler implements abilities.Ports {\n  freePort(): number {\n    return Number(execFileSync(process.execPath, ['-e', probe], { encoding: 'utf8' }));\n  }\n}\n"
defaultSource "typescript/time.ts" = "// Generated by LawSpec. Do not edit.\n// The default handler of lawspec.time's Clock: the system clock, kept from\n// going back by a monotonic clock. An Instant is microseconds since\n// 1970-01-01T00:00:00Z.\nimport * as data from '../lawspec_data.js';\nimport type * as abilities from '../lawspec_abilities/lawspec/time.js';\n\nconst wall = BigInt(Date.now()) * 1000n;\nconst monotonic = process.hrtime.bigint() / 1000n;\n\n/** The wall clock at start, moved on by the monotonic clock since. */\nexport function nowMicros(): bigint {\n  return wall + (process.hrtime.bigint() / 1000n - monotonic);\n}\n\nconst blocker = new Int32Array(new SharedArrayBuffer(4));\n\n/** The system clock. now never goes back; sleep blocks this thread. */\nexport class ClockHandler implements abilities.Clock {\n  now(): @@Instant@@ {\n    return new @@Instant@@(nowMicros());\n  }\n  sleep(value0: @@Duration@@): void {\n    const target = nowMicros() + value0.value;\n    for (let left = target - nowMicros(); left > 0n; left = target - nowMicros()) {\n      Atomics.wait(blocker, 0, 0, Math.max(Number(left) / 1000, 0));\n    }\n  }\n}\n"
